import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.IOException;import java.util.StringTokenizer;public class Main {static class FastScanner {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st;String next() {while (st == null || !st.hasMoreTokens()) {try {String l = br.readLine();if (l == null) return null;st = new StringTokenizer(l);} catch (IOException e) {return null;}}return st.nextToken();}int nextInt() {return Integer.parseInt(next());}}public static void main(String[] args) {FastScanner scanner = new FastScanner();int n = scanner.nextInt();int[] a = new int[n];int evens = 0, odds = 0;for (int i = 0; i < n; i++) {a[i] = scanner.nextInt();if (a[i] % 2 == 0) {evens++;} else {odds++;}}boolean targetEven = evens < odds;for (int i = 0; i < n; i++) {if (targetEven && a[i] % 2 == 0) {System.out.println(i + 1);return;}if (!targetEven && a[i] % 2 != 0) {System.out.println(i + 1);return;}}}}